import sys
import heapq


def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    g = int(data[1])
    c = [int(x) for x in data[2:2 + n]]
    k = [int(x) for x in data[2 + n:2 + 2 * n]]
    dp = [-1] * n
    dp[0] = c[0]
    heap = []
    p = 0
    best = -1
    if k[0] >= n:
        best = c[0]
    for i in range(1, n):
        limit = i - g
        while p <= limit:
            if dp[p] >= 0:
                heapq.heappush(heap, (dp[p], p))
            p += 1
        while heap:
            j = heap[0][1]
            if j + k[j] < i + 1:
                heapq.heappop(heap)
            else:
                break
        if heap:
            dp[i] = c[i] + heap[0][0]
            if i + k[i] >= n and (best < 0 or dp[i] < best):
                best = dp[i]
    print(best)


main()

