import sys

data = sys.stdin.read().split()
n = int(data[0])
g = int(data[1])
c = [int(x) for x in data[2:2 + n]]
k = [int(x) for x in data[2 + n:2 + 2 * n]]
INF = 1 << 62
size = 1
while size < n:
    size *= 2
tree = [INF] * (2 * size)


def chmin(lo, hi, v):
    # write v over every minute in [lo, hi] as a candidate cost
    if lo > hi:
        return
    lo += size
    hi += size + 1
    while lo < hi:
        if lo & 1:
            if v < tree[lo]:
                tree[lo] = v
            lo += 1
        if hi & 1:
            hi -= 1
            if v < tree[hi]:
                tree[hi] = v
        lo //= 2
        hi //= 2


def query(i):
    i += size
    res = tree[i]
    while i > 1:
        i //= 2
        if tree[i] < res:
            res = tree[i]
    return res


best = INF
for i in range(n):
    if i == 0:
        cur = c[0]
    else:
        got = query(i)
        cur = got + c[i] if got < INF else INF
    if cur < INF:
        if i + k[i] >= n and cur < best:
            best = cur
        chmin(i + g, min(i + k[i] - 1, n - 1), cur)
print(best if best < INF else -1)
